// Vector marker art: a 64-unit board-game piece in viewBox -32..32.
// T is the body (player) colour, D its shaded side; ink, cream and accents are fixed.
// Animated parts (orbit satellite, sparkles, flame flicker) are drawn by PlayerMarker.
export const INK='#1f1b2d',CREAM='#fff6e0';
export type MarkerMotion='orbit'|'twinkle'|'flicker'|'spin'|'pulse';
export interface Sparkle {x:number;y:number;size:number;phase:number}
export interface MarkerShape {body:(T:string,D:string)=>string;motion?:MarkerMotion;sparkles?:readonly Sparkle[]}
const hl=(d:string,w=3.5)=>`<path d="${d}" fill="none" stroke="#fff" stroke-width="${w}" stroke-linecap="round" opacity=".72"/>`;
const eyes=(x:number,y:number,rx:number,ry:number)=>`<ellipse cx="${-x}" cy="${y}" rx="${rx}" ry="${ry}" fill="${INK}"/><ellipse cx="${x}" cy="${y}" rx="${rx}" ry="${ry}" fill="${INK}"/><circle cx="${-x+1.1}" cy="${y-1.4}" r="1.2" fill="#fff"/><circle cx="${x+1.1}" cy="${y-1.4}" r="1.2" fill="#fff"/>`;
const cheeks=(x:number,y:number)=>`<ellipse cx="${-x}" cy="${y}" rx="3.3" ry="2.1" fill="#ff8fa3" opacity=".75"/><ellipse cx="${x}" cy="${y}" rx="3.3" ry="2.1" fill="#ff8fa3" opacity=".75"/>`;
const puck=(T:string,D:string)=>`<circle cy="4" r="22" fill="${D}" stroke="${INK}" stroke-width="4"/><circle cy="-1" r="22" fill="${T}" stroke="${INK}" stroke-width="4"/>`;
const star=(x:number,y:number,s:number)=>{const p=[[0,-1],[.32,-.32],[1,0],[.32,.32],[0,1],[-.32,.32],[-1,0],[-.32,-.32]];return p.map(([a,b])=>(x+a*s).toFixed(2)+','+(y+b*s).toFixed(2)).join(' ');};
export const sparkleSvg=(x:number,y:number,s:number)=>`<polygon points="${star(x,y,s)}" fill="${CREAM}" stroke="${INK}" stroke-width="1.6" stroke-linejoin="round"/>`;

